package com.kamyabpakhsh.staff;
import android.app.*;import android.os.*;import android.graphics.*;import android.graphics.Typeface;import android.view.*;import android.widget.*;import android.graphics.drawable.GradientDrawable;import android.content.*;import java.text.*;import java.util.*;
public class MainActivity extends Activity{
 int green=Color.rgb(0,200,120),dark=Color.rgb(5,18,14),panel=Color.rgb(15,39,31),soft=Color.rgb(238,247,243);LinearLayout root;SharedPreferences db;String current="";
 public void onCreate(Bundle b){super.onCreate(b);db=getSharedPreferences("kamyab",MODE_PRIVATE);getWindow().setStatusBarColor(dark);showLogin();}
 GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(r);return g;} TextView tx(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);v.setPadding(20,14,20,14);return v;} void base(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(24,20,24,20);root.setBackgroundColor(dark);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);setContentView(root);} EditText in(String h,boolean p){EditText e=new EditText(this);e.setHint(h);e.setSingleLine(true);e.setTextColor(Color.DKGRAY);e.setHintTextColor(Color.GRAY);e.setPadding(22,0,22,0);e.setBackground(bg(soft,22));if(p)e.setInputType(129);LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(-1,110);q.setMargins(0,10,0,0);e.setLayoutParams(q);return e;} Button bt(String s){Button b=new Button(this);b.setText(s);b.setTextSize(16);b.setTextColor(Color.WHITE);b.setBackground(bg(green,22));return b;} String role(){return current.equals("admin")?"مدیر":db.getString("role_"+current,"پرسنل");} boolean manager(){return current.equals("admin")||role().equals("مدیر");}
 void showLogin(){base();ImageView l=new ImageView(this);l.setImageResource(R.drawable.logo);l.setScaleType(ImageView.ScaleType.CENTER_INSIDE);root.addView(l,new LinearLayout.LayoutParams(-1,180));TextView t=tx("کامیاب پخش",29,Color.WHITE);t.setGravity(Gravity.CENTER);t.setTypeface(null,Typeface.BOLD);root.addView(t);TextView st=tx("سامانه هوشمند مدیریت و پرسنل",14,Color.LTGRAY);st.setGravity(Gravity.CENTER);root.addView(st);LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(24,24,24,24);card.setBackground(bg(Color.WHITE,30));root.addView(card);EditText u=in("نام کاربری",false),p=in("رمز عبور",true);card.addView(u);card.addView(p);CheckBox sh=new CheckBox(this);sh.setText("نمایش رمز عبور");sh.setTextColor(Color.DKGRAY);sh.setOnCheckedChangeListener((x,c)->p.setInputType(c?145:129));card.addView(sh);Button b=bt("ورود به سامانه");card.addView(b,new LinearLayout.LayoutParams(-1,110));b.setOnClickListener(v->{String us=u.getText().toString().trim(),pw=p.getText().toString();boolean ok=(us.equals("admin")&&pw.equals(db.getString("admin_pass","1234")))||(!us.isEmpty()&&pw.equals(db.getString("pass_"+us,"#")));if(ok){current=us;dash();}else Toast.makeText(this,"نام کاربری یا رمز عبور اشتباه است",0).show();});root.addView(tx("نسخه ۲.۲ • دستیار حسمان",12,Color.GRAY));}
 void head(String s){LinearLayout h=new LinearLayout(this);Button b=bt("بازگشت");b.setOnClickListener(v->dash());h.addView(b,new LinearLayout.LayoutParams(180,80));TextView t=tx(s,21,Color.WHITE);t.setTypeface(null,Typeface.BOLD);h.addView(t,new LinearLayout.LayoutParams(0,80,1));root.addView(h);} void dash(){base();TextView h=tx("کامیاب پخش",25,Color.WHITE);h.setTypeface(null,Typeface.BOLD);root.addView(h);root.addView(tx("سلام "+current+"  •  "+role(),14,Color.LTGRAY));TextView ai=tx("✦ حسمان\nدستیار هوشمند کامیاب پخش — برای گزارش، فروش و کارهای روزانه از من بپرس",16,Color.WHITE);ai.setTypeface(null,Typeface.BOLD);ai.setBackground(bg(panel,28));ai.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);ai.setOnClickListener(v->hesman());LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,125);ap.setMargins(0,12,0,12);root.addView(ai,ap);String[] a={"پرسنل","گزارش روزانه","ثبت سفارش","مطالبات","انبار","تحویل و توزیع","گزارش مدیریتی","حضور و غیاب","پیام‌ها","تغییر رمز"};GridLayout g=new GridLayout(this);g.setColumnCount(2);for(int i=0;i<a.length;i++){final int n=i;TextView c=tx(a[i],15,dark);c.setGravity(Gravity.CENTER);c.setTypeface(null,Typeface.BOLD);c.setBackground(bg(Color.WHITE,24));c.setOnClickListener(v->open(n));GridLayout.LayoutParams q=new GridLayout.LayoutParams();q.width=0;q.height=135;q.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);q.setMargins(7,7,7,7);g.addView(c,q);}ScrollView sc=new ScrollView(this);sc.addView(g);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));Button o=bt("خروج از حساب");o.setOnClickListener(v->{current="";showLogin();});root.addView(o,new LinearLayout.LayoutParams(-1,85));}
 boolean allowed(int n){if(manager())return true;String r=role();if(n==0||n==6)return false;if(r.equals("ویزیتور"))return n==1||n==2||n==3||n==7||n==8||n==9;if(r.contains("حسابدار"))return n==1||n==3||n==7||n==8||n==9;if(r.equals("انباردار"))return n==1||n==4||n==7||n==8||n==9;if(r.equals("تحویل‌دهنده")||r.equals("راننده"))return n==1||n==5||n==7||n==8||n==9;return n==1||n==7||n==8||n==9;} void open(int n){if(!allowed(n)){Toast.makeText(this,"شما به این بخش دسترسی ندارید",0).show();return;}if(n==0)staff();else if(n==1)form("گزارش روزانه","شرح فعالیت‌ها و اتفاقات امروز","ثبت گزارش","reports");else if(n==2)order();else if(n==3)form("پیگیری مطالبات","نام مشتری | مبلغ | مبلغ وصول | توضیحات","ثبت پیگیری","debts");else if(n==4)form("مدیریت انبار","نام کالا | ورود/خروج | تعداد | توضیحات","ثبت گردش","stock");else if(n==5)form("تحویل و توزیع","شماره فاکتور | مشتری | تحویل | وصول | توضیحات","ثبت تحویل","delivery");else if(n==6)reports();else if(n==7)attendance();else if(n==8)form("پیام‌ها","متن پیام یا یادداشت مهم","ثبت پیام","messages");else password();}
 void hesman(){base();head("حسمان • دستیار هوشمند");TextView intro=tx("✦ سلام، من حسمان هستم.\nدستیار کاری کامیاب پخش. سؤال یا درخواستت را بنویس.",17,Color.WHITE);intro.setBackground(bg(panel,25));root.addView(intro);ScrollView sc=new ScrollView(this);TextView chat=tx(db.getString("hesman_chat","هنوز گفت‌وگویی ثبت نشده است."),15,Color.WHITE);sc.addView(chat);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));EditText q=in("مثلاً: گزارش امروز را مرتب کن",false);root.addView(q);Button send=bt("ارسال به حسمان");root.addView(send,new LinearLayout.LayoutParams(-1,100));send.setOnClickListener(v->{String x=q.getText().toString().trim();if(x.isEmpty())return;String ans=smartReply(x);String old=db.getString("hesman_chat","");db.edit().putString("hesman_chat","شما: "+x+"\nحسمان: "+ans+"\n\n"+old).apply();hesman();});}
 String smartReply(String x){String s=x.toLowerCase();if(s.contains("گزارش"))return "برای گزارش کامل، فعالیت‌های انجام‌شده، فروش یا وصول، مشکلات امروز و کارهای باقی‌مانده را بنویس. من این اطلاعات را برای ثبت منظم می‌کنم.";if(s.contains("مطالب")||s.contains("وصول"))return "مطالبات را بر اساس نام مشتری، مبلغ بدهی، مبلغ وصول‌شده و توضیح پیگیری ثبت کن تا گزارش مدیریتی دقیق بماند.";if(s.contains("سفارش")||s.contains("فروش"))return "نام مشتری، کالاها، تعداد و مبلغ سفارش را وارد کن. سفارش از بخش ثبت سفارش ذخیره می‌شود.";if(s.contains("انبار"))return "برای گردش انبار نام کالا، نوع ورود یا خروج، تعداد و توضیح را ثبت کن.";if(s.contains("سلام"))return "سلام! من حسمان، دستیار کاری کامیاب پخش هستم. در گزارش، سفارش، مطالبات، انبار و کارهای روزانه کمکت می‌کنم.";return "درخواستت ثبت شد. نسخه فعلی حسمان دستیار داخلی برنامه است؛ برای پاسخ هوش مصنوعی آنلاین، اتصال امن سرور در مرحله بعد فعال می‌شود.";}
 void form(String title,String hint,String action,String key){base();head(title);EditText e=new EditText(this);e.setHint(hint);e.setGravity(Gravity.TOP|Gravity.RIGHT);e.setMinLines(7);e.setTextColor(Color.DKGRAY);e.setHintTextColor(Color.GRAY);e.setPadding(20,20,20,20);e.setBackground(bg(Color.WHITE,20));root.addView(e,new LinearLayout.LayoutParams(-1,0,1));Button b=bt(action);root.addView(b,new LinearLayout.LayoutParams(-1,105));b.setOnClickListener(v->{String x=e.getText().toString().trim();if(x.isEmpty()){Toast.makeText(this,"اطلاعات را وارد کنید",0).show();return;}save(key,x);e.setText("");Toast.makeText(this,"با موفقیت ثبت شد",0).show();});} void save(String k,String x){String old=db.getString(k,"");String now=new SimpleDateFormat("yyyy/MM/dd HH:mm",Locale.US).format(new Date());db.edit().putString(k,"["+now+"] "+current+" ("+role()+"): "+x+"\n"+old).apply();}
 void staff(){base();head("مدیریت پرسنل");EditText nm=in("نام و نام خانوادگی",false),u=in("نام کاربری جدید",false),p=in("رمز عبور",false);root.addView(nm);root.addView(u);root.addView(p);Spinner r=new Spinner(this);String[] rs={"ویزیتور","تحویل‌دهنده","حسابدار / صندوقدار","انباردار","راننده","مدیر"};r.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,rs));root.addView(r);Button add=bt("ایجاد / بروزرسانی حساب");root.addView(add,new LinearLayout.LayoutParams(-1,100));add.setOnClickListener(v->{String us=u.getText().toString().trim(),pw=p.getText().toString(),name=nm.getText().toString().trim();if(us.isEmpty()||pw.isEmpty()||name.isEmpty()||us.equals("admin")){Toast.makeText(this,"اطلاعات معتبر وارد کنید",0).show();return;}db.edit().putString("pass_"+us,pw).putString("role_"+us,r.getSelectedItem().toString()).putString("name_"+us,name).putString("staff_list",name+" — "+us+" — "+r.getSelectedItem()+"\n"+db.getString("staff_list","")).apply();Toast.makeText(this,"حساب ذخیره شد",0).show();staff();});ScrollView s=new ScrollView(this);s.addView(tx("پرسنل ثبت‌شده:\n"+db.getString("staff_list","هنوز حسابی ثبت نشده است."),15,Color.WHITE));root.addView(s,new LinearLayout.LayoutParams(-1,0,1));}
 void order(){base();head("ثبت سفارش");EditText c=in("نام مشتری",false),m=in("مبلغ سفارش",false);m.setInputType(2);root.addView(c);root.addView(m);EditText it=new EditText(this);it.setHint("نام کالاها، تعداد و توضیحات");it.setMinLines(5);it.setGravity(Gravity.TOP|Gravity.RIGHT);it.setBackground(bg(Color.WHITE,20));root.addView(it,new LinearLayout.LayoutParams(-1,0,1));Button b=bt("ثبت سفارش");root.addView(b,new LinearLayout.LayoutParams(-1,100));b.setOnClickListener(v->{if(c.getText().toString().trim().isEmpty())return;save("orders",c.getText()+" | مبلغ: "+m.getText()+" | "+it.getText());Toast.makeText(this,"سفارش ثبت شد",0).show();c.setText("");m.setText("");it.setText("");});}
 void attendance(){base();head("حضور و غیاب");Button i=bt("ثبت ورود"),o=bt("ثبت خروج");root.addView(i,new LinearLayout.LayoutParams(-1,105));root.addView(o,new LinearLayout.LayoutParams(-1,105));root.addView(tx("آخرین وضعیت:\n"+db.getString("att_"+current,"ثبت نشده"),16,Color.WHITE));i.setOnClickListener(v->att("ورود"));o.setOnClickListener(v->att("خروج"));} void att(String type){String t=type+" — "+new SimpleDateFormat("yyyy/MM/dd HH:mm:ss",Locale.US).format(new Date());db.edit().putString("att_"+current,t).apply();save("attendance",t);attendance();}
 void reports(){base();head("گزارش‌های مدیریتی");ScrollView s=new ScrollView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);String[] k={"reports","orders","debts","stock","delivery","attendance","messages"},n={"گزارش روزانه","سفارش‌ها","مطالبات","انبار","تحویل","حضور و غیاب","پیام‌ها"};for(int i=0;i<k.length;i++){TextView h=tx("● "+n[i],18,green);h.setTypeface(null,Typeface.BOLD);box.addView(h);box.addView(tx(db.getString(k[i],"موردی ثبت نشده است."),14,Color.WHITE));}s.addView(box);root.addView(s,new LinearLayout.LayoutParams(-1,0,1));}
 void password(){base();head("تغییر رمز عبور");EditText old=in("رمز فعلی",true),nw=in("رمز جدید",true),again=in("تکرار رمز جدید",true);root.addView(old);root.addView(nw);root.addView(again);Button b=bt("ذخیره رمز جدید");root.addView(b,new LinearLayout.LayoutParams(-1,105));b.setOnClickListener(v->{String cur=current.equals("admin")?db.getString("admin_pass","1234"):db.getString("pass_"+current,"");if(!old.getText().toString().equals(cur)){Toast.makeText(this,"رمز فعلی صحیح نیست",0).show();return;}if(nw.getText().length()<4||!nw.getText().toString().equals(again.getText().toString())){Toast.makeText(this,"رمز جدید معتبر نیست",0).show();return;}SharedPreferences.Editor e=db.edit();if(current.equals("admin"))e.putString("admin_pass",nw.getText().toString());else e.putString("pass_"+current,nw.getText().toString());e.apply();dash();});}
 @Override public void onBackPressed(){if(current.isEmpty())new AlertDialog.Builder(this).setMessage("می‌خواهید از برنامه خارج شوید؟").setNegativeButton("خیر",null).setPositiveButton("بله",(d,w)->finish()).show();else dash();}
}